def split_csv(line):
    n = len(line)
    if n == 0:
        return ['']

    fields = []
    i = 0

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote, must be comma or end of line
            if i == n:
                fields.append(''.join(chars))
                break
            elif line[i] == ',':
                fields.append(''.join(chars))
                i += 1
                continue
            else:
                return None
        else:
            # unquoted field, runs to next comma, must not contain a quote
            j = line.find(',', i)
            if j == -1:
                field = line[i:n]
                if '"' in field:
                    return None
                fields.append(field)
                i = n
                break
            else:
                field = line[i:j]
                if '"' in field:
                    return None
                fields.append(field)
                i = j + 1
                continue

    return fields

